import java.util.Optional;

public class PairCombinerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.function.Supplier<Object> call) {
        Object actual;
        try {
            actual = call.get();
        } catch (Throwable t) {
            actual = "threw " + t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    static void done() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    public static void main(String[] args) {
        check("both present", Optional.of("ababab"),
                PairCombiner.combine(Optional.of("ab"), Optional.of(3), (s, n) -> s.repeat(n)));
        check("first empty", Optional.empty(),
                PairCombiner.combine(Optional.<String>empty(), Optional.of(3), (s, n) -> s.repeat(n)));
        check("second empty", Optional.empty(),
                PairCombiner.combine(Optional.of("ab"), Optional.<Integer>empty(), (s, n) -> s.repeat(n)));
        check("merger is never called on an empty input", Optional.empty(),
                PairCombiner.combine(Optional.<String>empty(), Optional.of(3),
                        (s, n) -> { throw new IllegalStateException("must not run"); }));
        check("merger result may be a different type", Optional.of(5),
                PairCombiner.combine(Optional.of("ab"), Optional.of("cde"), (a, b) -> a.length() + b.length()));

        check("label with both parts", Optional.of("Paris-75"),
                PairCombiner.label(Optional.of("Paris"), Optional.of(75)));
        check("label without a code", Optional.empty(),
                PairCombiner.label(Optional.of("Paris"), Optional.empty()));
        check("label without a city", Optional.empty(),
                PairCombiner.label(Optional.empty(), Optional.of(75)));

        check("sum of two numbers", Optional.of(42), PairCombiner.sum(Optional.of(2), Optional.of(40)));
        check("sum with zero", Optional.of(7), PairCombiner.sum(Optional.of(7), Optional.of(0)));
        check("sum with a missing number", Optional.empty(),
                PairCombiner.sum(Optional.of(2), Optional.empty()));
        done();
    }
