import java.util.Optional;
import java.util.function.BiFunction;

/**
 * TASK: Complete PairCombiner.
 *
 * - combine(first, second, merger) returns an Optional holding
 *   merger.apply(a, b) when BOTH inputs are present, and an empty Optional
 *   otherwise. The merger must not be called at all when either input is
 *   empty. The idiom is first.flatMap(a -> second.map(b -> merger.apply(a, b))).
 *
 * - label(city, code) gives Optional["Paris-75"] when both parts are there and
 *   an empty Optional otherwise. Build it by calling combine.
 *
 * - sum(first, second) adds two optional numbers the same way, so
 *   sum(Optional.of(2), Optional.of(40)) -> Optional[42].
 *
 * Example: combine(Optional.of("ab"), Optional.of(3), (s, n) -> s.repeat(n))
 *          -> Optional[ababab]
 */
public class PairCombiner {

    public static <T, U, R> Optional<R> combine(Optional<T> first,
                                                Optional<U> second,
                                                BiFunction<T, U, R> merger) {
        return first.flatMap(a -> second.map(b -> merger.apply(a, b)));
    }

    public static Optional<String> label(Optional<String> city, Optional<Integer> code) {
        return combine(city, code, (name, number) -> name + "-" + number);
    }

    public static Optional<Integer> sum(Optional<Integer> first, Optional<Integer> second) {
        return combine(first, second, (a, b) -> a + b);
    }
}
